-- Signal Database (signal-database) v1 — sqlite
-- Synthetic sample data, CC0-1.0. Deterministic: the same spec and seed produce this byte for byte.
-- seed: catalogue:signal-database
-- Tables in dependency order; foreign keys are added after the data.

BEGIN;

CREATE TABLE "groups" (
    "group_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "group_name" TEXT NOT NULL
);

CREATE TABLE "group_settings" (
    "group_setting_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "group_id" INTEGER NOT NULL,
    "setting_key" TEXT NOT NULL,
    "setting_value" TEXT NOT NULL,
    FOREIGN KEY ("group_id") REFERENCES "groups" ("group_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "users" (
    "user_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "email" TEXT NOT NULL UNIQUE,
    "password_hash" TEXT NOT NULL,
    "phone_number" TEXT NOT NULL,
    "username" TEXT NOT NULL UNIQUE
);

CREATE TABLE "admin_audit_log" (
    "audit_log_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "action" TEXT NOT NULL,
    "action_time" TEXT NOT NULL,
    "admin_id" INTEGER NOT NULL,
    "target_group_id" INTEGER NOT NULL,
    "target_user_id" INTEGER NOT NULL,
    FOREIGN KEY ("admin_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("target_group_id") REFERENCES "groups" ("group_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("target_user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "admins" (
    "admin_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "blocked_users" (
    "block_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "blocked_at" TEXT NOT NULL,
    "blocked_user_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("blocked_user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "contacts" (
    "contact_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "contact_user_id" INTEGER NOT NULL,
    "created_at" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("contact_user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "group_chat_messages" (
    "group_message_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "group_id" INTEGER NOT NULL,
    "message_text" TEXT NOT NULL,
    "message_type" TEXT NOT NULL,
    "sender_id" INTEGER NOT NULL,
    "sent_at" TEXT NOT NULL,
    FOREIGN KEY ("group_id") REFERENCES "groups" ("group_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("sender_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "group_invitations" (
    "invitation_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "group_id" INTEGER NOT NULL,
    "invited_at" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("group_id") REFERENCES "groups" ("group_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "group_media" (
    "group_media_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "group_message_id" INTEGER NOT NULL,
    "media_type" TEXT NOT NULL,
    "media_url" TEXT NOT NULL,
    "uploaded_at" TEXT NOT NULL,
    FOREIGN KEY ("group_message_id") REFERENCES "group_chat_messages" ("group_message_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "group_members" (
    "group_member_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "group_id" INTEGER NOT NULL,
    "joined_at" TEXT NOT NULL,
    "role" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("group_id") REFERENCES "groups" ("group_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "group_mentions" (
    "group_mention_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "group_message_id" INTEGER NOT NULL,
    "mentioned_user_id" INTEGER NOT NULL,
    FOREIGN KEY ("group_message_id") REFERENCES "group_chat_messages" ("group_message_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("mentioned_user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "invitation_links" (
    "invite_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "group_id" INTEGER NOT NULL,
    "invite_link" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("group_id") REFERENCES "groups" ("group_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "messages" (
    "message_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "message_text" TEXT NOT NULL,
    "message_type" TEXT NOT NULL,
    "receiver_id" INTEGER NOT NULL,
    "sender_id" INTEGER NOT NULL,
    "sent_at" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    FOREIGN KEY ("receiver_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("sender_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "archived_messages" (
    "archived_message_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "archived_at" TEXT NOT NULL,
    "message_id" INTEGER NOT NULL,
    FOREIGN KEY ("message_id") REFERENCES "messages" ("message_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "deleted_messages" (
    "deleted_message_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "deleted_at" TEXT NOT NULL,
    "message_id" INTEGER NOT NULL,
    FOREIGN KEY ("message_id") REFERENCES "messages" ("message_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "media" (
    "media_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "media_type" TEXT NOT NULL,
    "media_url" TEXT NOT NULL,
    "message_id" INTEGER NOT NULL,
    "uploaded_at" TEXT NOT NULL,
    FOREIGN KEY ("message_id") REFERENCES "messages" ("message_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "message_history" (
    "history_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "message_id" INTEGER NOT NULL,
    "message_text" TEXT NOT NULL,
    "message_type" TEXT NOT NULL,
    "modified_at" TEXT NOT NULL,
    FOREIGN KEY ("message_id") REFERENCES "messages" ("message_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "message_reactions" (
    "reaction_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "message_id" INTEGER NOT NULL,
    "reaction_type" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("message_id") REFERENCES "messages" ("message_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "notifications" (
    "notification_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "message" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "pinned_messages" (
    "pinned_message_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "message_id" INTEGER NOT NULL,
    "pinned_at" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("message_id") REFERENCES "messages" ("message_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "settings" (
    "setting_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "setting_key" TEXT NOT NULL,
    "setting_value" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "spam_reports" (
    "report_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "report_reason" TEXT NOT NULL,
    "reported_by_user_id" INTEGER NOT NULL,
    "reported_user_id" INTEGER NOT NULL,
    FOREIGN KEY ("reported_by_user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("reported_user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "two_factor_authentication" (
    "twofa_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "is_enabled" INTEGER NOT NULL,
    "method" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "user_activity_log" (
    "activity_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "activity_details" TEXT NOT NULL,
    "activity_time" TEXT NOT NULL,
    "activity_type" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "user_badges" (
    "badge_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "awarded_at" TEXT NOT NULL,
    "badge_type" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "user_devices" (
    "device_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "device_name" TEXT NOT NULL,
    "device_token" TEXT NOT NULL,
    "last_used_at" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "user_mentions" (
    "mention_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "mentioned_user_id" INTEGER NOT NULL,
    "message_id" INTEGER NOT NULL,
    FOREIGN KEY ("mentioned_user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("message_id") REFERENCES "messages" ("message_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "user_preferences" (
    "preference_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "preference_key" TEXT NOT NULL,
    "preference_value" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "voice_messages" (
    "voice_id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "duration" INTEGER NOT NULL,
    "message_id" INTEGER NOT NULL,
    "uploaded_at" TEXT NOT NULL,
    "voice_url" TEXT NOT NULL,
    FOREIGN KEY ("message_id") REFERENCES "messages" ("message_id") DEFERRABLE INITIALLY DEFERRED
);

